package com.activeandroid;

import java.util.List;

import com.activeandroid.serializer.TypeSerializer;

/**
 * Models and type serializers of one module, generated by
 * {@link com.activeandroid.internal.AnnotationProcessor} and loaded via
 * {@link java.util.ServiceLoader}, so they need not be found by scanning the dex.
 */
public interface ModelRegistry {

	/** Concrete subclasses of {@link Model}. */
	List<Class<? extends Model>> getModelClasses();

	/** Concrete subclasses of {@link TypeSerializer}. */
	List<Class<? extends TypeSerializer>> getTypeSerializers();
}
